<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Resume Builder</title><link rel="stylesheet" href="<?= base_url('assets/css/resume-maker.css') ?>"></head><body><main class="builder-shell"><section class="editor"><div class="topbar"><a class="back" href="<?= site_url('/') ?>">← Templates</a><b><?= strtoupper($paperSize) ?> Resume</b></div><form id="resumeForm" enctype="multipart/form-data"><input type="hidden" name="paper_size" value="<?= esc($paperSize) ?>"><input type="hidden" name="uuid" value="<?= esc($resume['uuid']??'') ?>"><h2>Basic Information</h2><div class="grid"><label class="wide">Full Name<input required name="full_name" value="<?= v($d,'full_name') ?>"></label><label class="wide">Street / Barangay<input name="street" value="<?= v($d,'street') ?>"></label><label class="wide">Town / Province<input name="location" value="<?= v($d,'location') ?>"></label><label>Contact Number<input name="contact" value="<?= v($d,'contact') ?>"></label><label>Email<input required type="email" name="email" value="<?= v($d,'email') ?>"></label><label>Date of Birth<input required type="date" name="date_of_birth" value="<?= v($d,'date_of_birth') ?>"></label><label>Citizenship<input name="citizenship" value="<?= v($d,'citizenship','Filipino') ?>"></label><label>Sex<select name="sex"><option></option><?php foreach(['Male','Female','Prefer not to say'] as $o):?><option <?=($d['sex']??'')===$o?'selected':''?>><?= $o ?></option><?php endforeach?></select></label><label>Civil Status<input name="civil_status" value="<?= v($d,'civil_status') ?>"></label><label>Height<input name="height" value="<?= v($d,'height') ?>"></label><label>Weight<input name="weight" value="<?= v($d,'weight') ?>"></label><label class="wide">Languages / Dialects<div class="tag-input" id="languageTags"><div class="tag-list" id="languageTagList"></div><input id="languageEntry" type="text" placeholder="Type a language, then press Enter or comma"></div><input type="hidden" id="languages" name="languages" value="<?= v($d,'languages') ?>"><small class="hint">Press Enter or comma to add each language.</small></label><label class="wide">Photo<input type="file" name="photo" accept="image/jpeg,image/png,image/webp"></label></div><h2>Skills & Qualifications</h2><div id="skillsWrap"><?php foreach(($d['skills']??['']) as $i=>$x):?><div class="repeat"><input name="skills[]" value="<?=esc($x)?>" placeholder="Skill or qualification"><button type="button" class="remove">×</button></div><?php endforeach?></div><button type="button" class="add" data-add="skill">+ Add Skill</button><h2>Educational Attainment <small>Max 5</small></h2><div id="educationWrap"></div><button type="button" class="add" data-add="education">+ Add Education</button><h2>Achievements <small>Max 5</small></h2><div id="achievementsWrap"></div><button type="button" class="add" data-add="achievement">+ Add Achievement</button><h2>Character References <small>Max 5</small></h2><div id="referencesWrap"></div><button type="button" class="add" data-add="reference">+ Add Reference</button><div id="errors"></div><div class="actions"><button type="button" id="previewBtn" class="btn secondary">Update Preview</button><button class="btn" type="submit">Save & Generate PDF</button></div></form></section><aside class="preview-pane"><div class="preview-head"><b>Live Preview</b><span>Changes are saved locally while you type.</span></div><iframe id="previewFrame" title="Resume preview"></iframe></aside></main><script>window.RESUME_DATA=<?=json_encode($d,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG)?>;window.SAVE_URL='<?=site_url('resume/save')?>';</script><script src="<?= base_url('assets/js/resume-maker.js') ?>"></script></body></html>
